<script setup>
import {ref,computed} from 'vue';
import {can,fieldAccess,money,cents,vendorFields,approvalStage,approvalStageLabel,approvalRequirement} from './domain.js';
import {poStatus,purchaseApprovals,canPOAct,inventory,quantity,qty,purchaseCost} from './procurement.js';
const props=defineProps(['state','user','tenantId','page','busy','execute','failure']);
const localToday=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');};
const approvals=p=>purchaseApprovals(props.state,p);
const approvedDate=p=>poStatus(props.state,p)==='Approved'?approvals(p).at(-1)?.at:null;
const approveLabel=p=>approvalStageLabel(approvalStage(props.state,props.user,props.tenantId,p,props.state.purchaseEvents.map(e=>({...e,amendmentId:e.purchaseOrderId})),'purchase_order'));
const approvalDate=s=>s?new Date(s).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}):'Pending';
const dialog=ref(''),form=ref({}),error=ref(''),selected=ref(''),query=ref('');
const allowed=(a,f='purchase_order',t=props.tenantId)=>can(props.state,props.user,t,a,f);
const field=(k,f='purchase_order')=>fieldAccess(props.state,props.user,props.tenantId,k,f);
const editable=computed(()=>['amount','description','materials','order_date'].every(k=>field(k)==='edit'));
const stockEditable=computed(()=>['materials','quantity'].every(k=>field(k,'inventory')==='edit'));
const orders=computed(()=>props.state.purchaseOrders.filter(p=>p.tenantId===props.tenantId&&allowed('view')&&(p.number+' '+p.vendor+' '+p.description).toLowerCase().includes(query.value.toLowerCase())));
const active=computed(()=>orders.value.find(p=>p.id===selected.value));
const stock=computed(()=>allowed('view','inventory')?inventory(props.state,props.tenantId):[]);
const movements=computed(()=>props.state.stockMovements.filter(m=>m.tenantId===props.tenantId).slice().reverse());
const vendors=computed(()=>props.state.vendors.filter(v=>v.tenantId===props.tenantId&&!v.deleted));
const extra=computed(()=>{const version=form.value.formVersion;return props.state.forms.filter(f=>f.id==='purchase_order'&&(!version||f.version===version)).sort((a,b)=>b.version-a.version)[0]?.fields||[];});
const targets=computed(()=>props.state.tenants.filter(t=>!t.deleted&&t.id!==props.tenantId&&allowed('create','inventory',t.id)&&['materials','quantity'].every(k=>fieldAccess(props.state,props.user,t.id,k,'inventory')==='edit')));
const lotName=id=>props.state.stockLots.find(l=>l.id===id)?.material||'Restricted material';
const projectName=id=>props.state.tenants.find(t=>t.id===id)?.name||'Another project';
const who=id=>props.state.users.find(u=>u.id===id)?.name||'Project user';
const remaining=(p,l)=>l.quantityMilli-props.state.stockMovements.filter(m=>m.kind==='receipt'&&m.lineId===l.id&&m.tenantId===props.tenantId).reduce((n,m)=>n+m.quantityMilli,0);
function open(kind,p,l){error.value='';dialog.value=kind;if(kind==='purchase-order')form.value=p?{...JSON.parse(JSON.stringify(p)),orderDate:p.orderDate||p.createdAt.slice(0,10),lines:p.lines.map(l=>({...l,quantity:String(l.quantityMilli/1000),price:String(l.rate/100)}))}:{number:'PO-'+(props.state.tenants.find(t=>t.id===props.tenantId)?.code||'PROJECT')+'-'+String(props.state.purchaseOrders.filter(p=>p.tenantId===props.tenantId).length+1).padStart(3,'0'),orderDate:localToday(),vendorId:'',description:'',data:{},lines:[{kind:'purchase',material:'',unit:'unit',quantity:'1',price:''}]};else if(kind==='purchase-receive')form.value={id:p.id,lineId:l.id,material:l.material,unit:l.unit,quantity:String(remaining(p,l)/1000)};else form.value={lotId:p.id,material:p.material,unit:p.unit,quantity:'',targetTenantId:'',reason:''};}
async function save(){try{let data={...form.value};if(dialog.value==='purchase-order')data.lines=form.value.lines.map(l=>({...l,quantityMilli:quantity(l.quantity),rate:cents(l.price)}));else data.quantityMilli=quantity(form.value.quantity);const result=await props.execute(dialog.value,data,dialog.value==='purchase-order'?'Purchase order draft saved':dialog.value==='purchase-receive'?'Materials received into inventory':dialog.value==='inventory-transfer'?'Stock transferred without adding purchase cost':'Stock issued for project use');if(result?.ok)dialog.value='';}catch(e){error.value=e.message;}}
function action(p,a){props.execute('purchase-transition',{id:p.id,action:a},'Purchase order '+(a==='approve'?'approval recorded':a==='review'?'reviewed':a==='submit'?'submitted':'rejected'));}
function estimate(){try{return money(form.value.lines.reduce((n,l)=>n+Number((BigInt(quantity(l.quantity))*BigInt(cents(l.price))+500n)/1000n),0));}catch{return 'Complete line quantities and rates';}}
</script>
<template><template v-if="page==='purchases'"><div class="stats-grid procurement-stats"><div class="stat-card primary-stat"><div class="stat-label">Approved purchase orders</div><strong>{{field('amount')==='hidden'?'Restricted':money(purchaseCost(state,tenantId))}}</strong><span>Purchased materials + rentals · including tax</span></div><div class="stat-card"><div class="stat-label">Awaiting approval</div><strong>{{orders.filter(p=>!['Draft','Approved','Rejected'].includes(poStatus(state,p))).length}}</strong><span>Excluded from committed project cost</span></div><div class="stat-card"><div class="stat-label">Owned material lots</div><strong>{{stock.length}}</strong><span>Rentals are excluded from owned inventory</span></div></div><section class="panel"><div class="panel-top"><div><h2>Purchase orders</h2><p>Buy materials or rent equipment with superuser-controlled approvals.</p></div><v-btn v-if="tenantId&&allowed('create')&&editable" color="primary" prepend-icon="mdi-plus" @click="open('purchase-order')">New purchase order</v-btn></div><div class="table-toolbar"><v-text-field v-model="query" prepend-inner-icon="mdi-magnify" label="Search purchase orders" density="compact" hide-details/></div><div class="table-scroll"><table class="orders-table"><thead><tr><th>PURCHASE ORDER</th><th>ORDERED MATERIAL</th><th>SUPPLIER</th><th>APPROVED BY</th><th>APPROVED DATE</th><th v-if="field('amount')!=='hidden'">VALUE</th><th>STATUS</th><th></th></tr></thead><tbody><tr v-for="p in orders" :key="p.id"><td><button class="order-link" @click="selected=p.id">{{p.number}}</button><span class="cell-secondary">{{field('order_date')==='hidden'?'Restricted':approvalDate(p.orderDate||p.createdAt)}}</span></td><td class="scope-cell"><div v-for="l in p.lines" :key="l.id">{{l.material}}<span class="cell-secondary">{{qty(l.quantityMilli)}} {{l.unit}} · {{l.kind==='rental'?'Rental':'Purchase'}}</span></div><span v-if="!p.lines.length">Restricted</span></td><td>{{p.vendor}}</td><td><div v-for="e in approvals(p)" :key="e.id">{{who(e.actorId)}}<span class="cell-secondary">{{approvalStageLabel(e.stage)}}</span></div><span v-if="!approvals(p).length">Pending</span></td><td>{{approvalDate(approvedDate(p))}}<span class="cell-secondary">{{approvedDate(p)?'Final approval':'Not fully approved'}}</span></td><td v-if="field('amount')!=='hidden'"><strong>{{money(p.total)}}</strong><span class="cell-secondary">Including tax</span></td><td><span :class="['status-badge',poStatus(state,p)==='Approved'?'green':poStatus(state,p)==='Rejected'?'red':poStatus(state,p)==='Draft'?'gray':'amber']">{{poStatus(state,p)}}</span></td><td><v-btn variant="text" size="small" @click="selected=p.id">View</v-btn></td></tr><tr v-if="!orders.length"><td colspan="8" class="empty-state">{{allowed('view')?'No purchase orders yet.':'Your roles do not grant access to purchase orders.'}}</td></tr></tbody></table></div></section></template>
<template v-else><div class="workflow-banner"><v-icon color="primary">mdi-package-variant-closed</v-icon><div><strong>Carry unused materials to another project</strong><p>Receive approved purchases, record stock used on site, or transfer unused quantities. Transfers do not add project cost.</p></div></div><section class="panel"><div class="panel-top"><div><h2>Available project inventory</h2><p>Stock is tracked by purchase order line and unit.</p></div></div><div class="table-scroll"><table class="orders-table"><thead><tr><th>MATERIAL</th><th>AVAILABLE</th><th>ORIGIN PROJECT</th><th>ACTIONS</th></tr></thead><tbody><tr v-for="l in stock" :key="l.id"><td>{{field('materials','inventory')==='hidden'?'Restricted':l.material}}<span class="cell-secondary">Lot {{l.id.slice(0,8)}}</span></td><td>{{field('quantity','inventory')==='hidden'?'Restricted':qty(l.available)+' '+(l.unit||'')}}</td><td>{{projectName(l.originTenantId)}}</td><td><div class="heading-actions" v-if="allowed('edit','inventory')&&stockEditable"><v-btn size="small" variant="outlined" @click="open('inventory-transfer',l)">Transfer</v-btn><v-btn size="small" variant="text" @click="open('inventory-issue',l)">Issue for use</v-btn></div></td></tr><tr v-if="!stock.length"><td colspan="4" class="empty-state">{{allowed('view','inventory')?'No stock available. Receive purchased materials from an approved purchase order.':'Your roles do not grant inventory access.'}}</td></tr></tbody></table></div></section><section class="panel mt-6" v-if="allowed('view','inventory')"><div class="panel-top"><h2>Stock movement history</h2></div><div class="table-scroll"><table class="orders-table"><thead><tr><th>MATERIAL</th><th>MOVEMENT</th><th>QUANTITY</th><th>PROJECT / REASON</th><th>RECORDED BY</th></tr></thead><tbody><tr v-for="m in movements" :key="m.id"><td>{{field('materials','inventory')==='hidden'?'Restricted':lotName(m.lotId)}}</td><td>{{m.kind}}</td><td>{{field('quantity','inventory')==='hidden'?'Restricted':(m.quantityMilli>0?'+':'')+qty(m.quantityMilli)}}</td><td class="scope-cell">{{m.counterpartyId?projectName(m.counterpartyId)+' · ':''}}{{m.reason||'Approved PO receipt'}}</td><td>{{who(m.actorId)}}<span class="cell-secondary">{{new Date(m.at).toLocaleDateString('en-IN')}}</span></td></tr><tr v-if="!movements.length"><td colspan="5" class="empty-state">No stock movements recorded.</td></tr></tbody></table></div></section></template>
<v-dialog :model-value="!!active" @update:model-value="v=>{if(!v)selected=''}" max-width="1000"><v-card v-if="active"><v-card-title class="dialog-title">{{active.number}}<v-btn icon="mdi-close" variant="text" aria-label="Close purchase order" @click="selected=''"/></v-card-title><v-card-text><div class="approval-head"><span class="status-badge blue">{{poStatus(state,active)}}</span><strong>{{money(active.total)}}</strong></div><div class="po-reference mt-4"><div><small>Supplier</small><strong>{{active.vendor}}</strong></div><div><small>Purchase order date</small><strong>{{field('order_date')==='hidden'?'Restricted':approvalDate(active.orderDate||active.createdAt)}}</strong></div><div><small>Approved by</small><strong>{{approvals(active).map(e=>who(e.actorId)+' ('+approvalStageLabel(e.stage)+')').join(', ')||'Pending'}}</strong></div><div><small>Approved date</small><strong>{{approvalDate(approvedDate(active))}}</strong></div><div><small>Value including tax</small><strong>{{money(active.total)}}</strong></div></div><p class="scope-detail mt-5">{{active.description}}</p><div class="vendor-brief"><h3>{{active.vendor}}</h3><p class="small muted mt-2">Vendor details recorded when the order was created</p><dl v-if="active.vendorSnapshot"><template v-for="k in vendorFields.filter(k=>active.vendorSnapshot[k])" :key="k"><dt>{{k}}</dt><dd>{{active.vendorSnapshot[k]}}</dd></template></dl></div><div class="table-scroll"><table class="orders-table"><thead><tr><th>ORDERED MATERIAL</th><th>TYPE</th><th>QUANTITY</th><th v-if="field('amount')!=='hidden'">RATE / TOTAL</th><th>INVENTORY</th></tr></thead><tbody><tr v-for="l in active.lines" :key="l.id"><td>{{l.material}}</td><td>{{l.kind==='rental'?'Rental':'Purchase'}}</td><td>{{qty(l.quantityMilli)}} {{l.unit}}</td><td v-if="field('amount')!=='hidden'">{{money(l.rate)}} / {{money(l.total)}}</td><td><span v-if="l.kind==='rental'">Cost only · no owned stock</span><template v-else><span class="cell-secondary">{{qty(remaining(active,l))}} {{l.unit}} to receive</span><v-btn v-if="poStatus(state,active)==='Approved'&&remaining(active,l)>0&&allowed('create','inventory')&&stockEditable" variant="outlined" size="small" class="mt-2" @click="open('purchase-receive',active,l)">Receive</v-btn></template></td></tr></tbody></table></div><div class="custom-data"><div v-for="(value,key) in active.data" :key="key"><small>{{key}}</small><strong>{{value}}</strong></div></div><div class="approval-actions"><v-btn v-if="poStatus(state,active)==='Draft'&&allowed('edit')&&editable&&(active.createdBy===user.id||user.superuser)" variant="outlined" @click="open('purchase-order',active)">Edit draft</v-btn><v-btn v-for="a in ['submit','review','approve','reject'].filter(a=>canPOAct(state,user,tenantId,active,a))" :key="a" :color="a==='reject'?'error':'primary'" variant="outlined" :loading="busy" @click="action(active,a)">{{a==='approve'?approveLabel(active):a==='submit'?'Submit':a==='review'?'Mark reviewed':'Reject'}}</v-btn></div><p class="small muted mt-4">{{approvalRequirement(active)}}. Approved orders add their full value to project cost.</p><div v-for="e in state.purchaseEvents.filter(e=>e.purchaseOrderId===active.id)" :key="e.id" class="event-line"><v-icon size="15">mdi-check-circle-outline</v-icon>{{e.action}} {{e.stage?approvalStageLabel(e.stage):''}} · {{who(e.actorId)}} · {{new Date(e.at).toLocaleString('en-IN')}}</div></v-card-text></v-card></v-dialog>
<v-dialog :model-value="!!dialog" @update:model-value="v=>{if(!v)dialog=''}" max-width="980"><v-card><v-card-title class="dialog-title">{{dialog==='purchase-order'?(form.id?'Edit purchase order draft':'New purchase order'):dialog==='purchase-receive'?'Receive purchased materials':dialog==='inventory-transfer'?'Transfer unused materials':'Issue materials for site use'}}<v-btn icon="mdi-close" variant="text" aria-label="Close material dialog" @click="dialog=''"/></v-card-title><v-card-text><v-alert v-if="error||failure" type="error" class="mb-4">{{error||failure}}</v-alert><template v-if="dialog==='purchase-order'"><div class="form-two-columns"><v-text-field v-model="form.number" label="Purchase order number *"/><v-select v-model="form.vendorId" :items="vendors.map(v=>({title:v.name,value:v.id}))" label="Supplier *"/></div><v-text-field v-model="form.orderDate" type="date" label="Purchase order date *"/><v-text-field v-model="form.description" label="Description *"/><div v-for="(l,i) in form.lines" :key="i" class="purchase-line"><div class="form-two-columns"><v-text-field v-model="l.material" label="Ordered material / equipment *"/><v-select v-model="l.kind" :items="[{title:'Purchase → owned inventory on receipt',value:'purchase'},{title:'Rental → project cost only',value:'rental'}]" label="Line type"/></div><div class="purchase-numbers"><v-text-field v-model="l.quantity" label="Quantity *" inputmode="decimal"/><v-text-field v-model="l.unit" label="Unit (tonne, bag, day) *"/><v-text-field v-model="l.price" label="Rate per unit incl. tax (₹) *" inputmode="decimal"/><v-btn icon="mdi-delete-outline" color="error" variant="text" :disabled="form.lines.length===1" :aria-label="'Remove line '+(i+1)" @click="form.lines.splice(i,1)"/></div></div><v-btn prepend-icon="mdi-plus" variant="outlined" @click="form.lines.push({kind:'purchase',material:'',unit:'unit',quantity:'1',price:''})">Add material line</v-btn><div class="detail-total mt-5"><span>Purchase order total · including tax</span><strong>{{estimate()}}</strong><small>Rentals include the hire period in the quantity or rate. Submitted drafts cannot be edited.</small></div><template v-for="f in extra" :key="f.key"><v-text-field v-if="field(f.key)==='edit'" v-model="form.data[f.key]" :label="f.label+(f.required?' *':'')" :type="f.type==='date'?'date':f.type==='number'?'number':'text'" class="mt-4"/></template></template><template v-else><p class="dialog-context">{{form.material}} · {{form.unit}}</p><v-text-field v-model="form.quantity" label="Quantity *" inputmode="decimal"/><template v-if="dialog!=='purchase-receive'"><v-select v-if="dialog==='inventory-transfer'" v-model="form.targetTenantId" :items="targets.map(t=>({title:t.name,value:t.id}))" label="Destination project *"/><v-text-field v-model="form.reason" label="Reason / site use reference *"/><v-alert type="info" variant="tonal">This records a stock movement. The original purchase cost remains on its purchasing project and is never added again.</v-alert></template></template></v-card-text><v-card-actions class="dialog-actions"><v-btn @click="dialog=''">Cancel</v-btn><v-spacer/><v-btn color="primary" variant="flat" :loading="busy" @click="save">{{dialog==='purchase-order'?'Save draft':dialog==='purchase-receive'?'Receive into inventory':dialog==='inventory-transfer'?'Transfer stock':'Issue stock'}}</v-btn></v-card-actions></v-card></v-dialog>
</template>
